function simple(topic, slug, prompt, options, answer, explanation, figure) {
  return { id: `math-4-${topic}-${slug}`, bank: `mathematics-4.${topic}`, level: 'simple', prompt, options, answer, explanation, figure };
}

function challenge(topic, slug, prompt, parts, explanation, figure) {
  return { id: `math-4-${topic}-${slug}`, bank: `mathematics-4.${topic}`, level: 'challenge', prompt, parts, explanation, figure };
}

function part(label, unit, answer, tolerance = 0) {
  return { label, unit, answer, tolerance };
}

function diagram(caption, alt, height, drawing) {
  return {
    caption,
    alt,
    svg: `<svg viewBox="0 0 480 ${height}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" font-family="system-ui, sans-serif" font-size="16" fill="#23324b">${drawing}</svg>`,
  };
}

function dataTable(caption, headers, rows) {
  return { caption, headers, rows };
}

