const lawsOfMotion = [
  simple(4, 'weight-from-mass',
    'A particle has mass 7.4 kg. Take g = 10 m s⁻². What is its weight?',
    ['7.4 N', '0.74 N', '17.4 N', '74 N'], 3,
    'Weight equals mass multiplied by gravitational acceleration, giving 7.4 × 10 = 74 N.'),
  simple(4, 'acceleration-under-opposing-forces',
    'An 8 kg trolley experiences a driving force of 36 N to the right and resistance of 12 N to the left. What is its acceleration?',
    ['3 m s⁻² rightwards', '6 m s⁻² rightwards', '4.5 m s⁻² rightwards', '3 m s⁻² leftwards'], 0,
    'The resultant horizontal force is 36 − 12 = 24 N to the right. Divide by 8 kg to get 3 m s⁻² to the right.'),
  simple(4, 'box-sliding-on-rough-floor',
    'A 3.5 kg box slides to the right on a horizontal floor under a horizontal pull of 14 N. The coefficient of friction is 0.2 and g = 10 m s⁻². What is its acceleration?',
    ['4 m s⁻² rightwards', '2 m s⁻² leftwards', '2 m s⁻² rightwards', '6 m s⁻² rightwards'], 2,
    'The reaction is 35 N, so friction is 0.2 × 35 = 7 N to the left. The resultant is 7 N rightwards, giving a = 7 ÷ 3.5 = 2 m s⁻² rightwards.'),
  simple(4, 'vertical-acceleration-under-tension',
    'A 2 kg load is raised vertically by a string with tension 30 N. Take g = 10 m s⁻² and neglect air resistance. Find its acceleration.',
    ['10 m s⁻² upwards', '5 m s⁻² upwards', '15 m s⁻² downwards', '5 m s⁻² downwards'], 1,
    'The weight is 20 N. The resultant force is 30 − 20 = 10 N upwards, giving acceleration 10 ÷ 2 = 5 m s⁻² upwards.'),
  simple(4, 'reaction-in-descending-lift',
    'A 3.5 kg package rests on the floor of a lift accelerating downwards at 2 m s⁻². Take g = 10 m s⁻². Find the upward contact force from the floor.',
    ['7 N', '35 N', '42 N', '28 N'], 3,
    'Take downwards as positive. The weight minus the contact force equals 3.5 × 2. This gives 35 − 7 = 28 N for the contact force.'),
  simple(4, 'freely-sliding-smooth-incline',
    'A particle is released on a smooth plane inclined at angle θ to the horizontal. Given sin θ = 0.6 and g = 10 m s⁻², what is its acceleration?',
    ['6 m s⁻² down the plane', '8 m s⁻² down the plane', '10 m s⁻² down the plane', '6 m s⁻² up the plane'], 0,
    'The weight component down the plane is mg sin θ. Divide by mass to get g sin θ = 6 m s⁻² down the plane.'),
  simple(4, 'towing-rope-tension',
    'A car tows a 500 kg trailer with a light horizontal rope. Both accelerate forwards at 1.2 m s⁻² on a level road. Ignore resistance on the trailer. Find the tension in the rope.',
    ['417 N', '600 N', '5000 N', '6000 N'], 1,
    'Apply Newton’s second law to the trailer. The rope supplies the entire horizontal resultant, giving tension 500 × 1.2 = 600 N.'),
  simple(4, 'rigid-rod-thrust',
    'A powered trolley uses a light horizontal rod in compression to push an unpowered trolley of mass 3 kg along a straight smooth track. Their acceleration is 4 m s⁻². Find the thrust in the rod.',
    ['0.75 N', '7 N', '30 N', '12 N'], 3,
    'The thrust provides the horizontal resultant on the unpowered trolley. It is 3 × 4 = 12 N.'),
  simple(4, 'two-equal-hanging-masses',
    'Two particles of mass 0.8 kg each hang from opposite ends of a light inextensible string passing over a smooth pulley. The system is released from rest. Take g = 10 m s⁻². Find the tension.',
    ['0 N', '0.8 N', '8 N', '16 N'], 2,
    'The equal weights balance so the system has zero acceleration. Each particle’s weight is 0.8 × 10 = 8 N and is balanced by the tension.'),
  simple(4, 'rough-plane-sliding-upwards',
    'A 2.5 kg particle slides up a rough plane with no applied pull. The component of its weight parallel to the plane is 15 N and the friction has magnitude 5 N. What is the acceleration?',
    ['8 m s⁻² down the plane', '4 m s⁻² down the plane', '4 m s⁻² up the plane', '8 m s⁻² up the plane'], 0,
    'Both friction and the parallel component of weight act down the plane while the particle moves up. Divide their sum, 20 N, by 2.5 kg to obtain 8 m s⁻² down the plane.'),

  challenge(4, 'connected-hanging-particles',
    'Two particles of masses 4 kg and 6 kg are attached to opposite ends of a light inextensible string over a smooth pulley. They are released with the string taut. Take g = 10 m s⁻².',
    [part('Find the magnitude of the acceleration.', 'm s⁻²', 2), part('Find the string tension.', 'N', 48)],
    'The 6 kg particle moves down. Combining the equations 60 − T = 6a and T − 40 = 4a gives 20 = 10a. Hence a = 2 and T = 40 + 4 × 2 = 48 N.'),
  challenge(4, 'rough-table-and-pulley',
    'The two particles shown are joined by a taut light inextensible string over a smooth pulley. A slides towards the pulley, and the coefficient of friction at the table is 0.25. Take g = 10 m s⁻².',
    [part('Find the magnitude of the acceleration to 3 significant figures.', 'm s⁻²', 1.67, 0.005),
     part('Find the string tension.', 'N', 25)],
    'Friction on A is 0.25 × 6 × 10 = 15 N. Write T − 15 = 6a for A and 30 − T = 3a for B. Adding gives 9a = 15, so a = 5/3 m s⁻² and T = 15 + 6 × 5/3 = 25 N.',
    tablePulley),
  challenge(4, 'smooth-incline-and-pulley',
    'A 5 kg particle A rests on a smooth plane inclined at θ to the horizontal, where sin θ = 0.6. A light inextensible string runs parallel to the plane, over a smooth pulley at the top, then vertically down to a 7 kg particle B. The string is taut when the particles are released. Take g = 10 m s⁻².',
    [part('Find the magnitude of acceleration to 3 significant figures.', 'm s⁻²', 3.33, 0.005),
     part('Find the string tension to 3 significant figures.', 'N', 46.7, 0.05)],
    'The downhill component of A’s weight is 5 × 10 × 0.6 = 30 N. The equations along the string are T − 30 = 5a and 70 − T = 7a, so a = 40/12 and T = 30 + 5 × 40/12 ≈ 46.7 N.'),
  challenge(4, 'rough-slope-out-and-back',
    'A 5 kg particle starts up a rough plane at 12 m s⁻¹. The inclination θ has sin θ = 0.6 and cos θ = 0.8. The coefficient of friction is 0.25. The particle stops momentarily and then slides back down. Take g = 10 m s⁻².',
    [part('Find the time to the momentary stop.', 's', 1.5),
     part('Find its speed on returning to its starting point, to 3 significant figures.', 'm s⁻¹', 8.49, 0.005)],
    'The downhill weight component is 30 N and friction has magnitude 0.25 × 40 = 10 N. On the way up both forces point downhill, giving deceleration 8 m s⁻². The particle stops after 1.5 s and 9 m. On the way down friction points uphill, so acceleration is (30 − 10)/5 = 4 m s⁻². After 9 m its speed is √(2 × 4 × 9) = 8.49 m s⁻¹.'),
  challenge(4, 'car-trailer-and-two-resistances',
    'A 900 kg car tows a 300 kg trailer with a taut light horizontal rope. The road is level. The driving force is 1800 N and the resistances on the car and trailer are 200 N and 100 N respectively.',
    [part('Find their common acceleration.', 'm s⁻²', 1.25), part('Find the rope tension.', 'N', 475)],
    'For the car and trailer together the forward resultant is 1800 − 200 − 100 = 1500 N. Dividing by 1200 kg gives 1.25 m s⁻². For the trailer alone, T − 100 = 300 × 1.25, so T = 475 N.'),
  challenge(4, 'driving-cart-and-compressed-rod',
    'A 5 kg powered trolley pushes a 3 kg unpowered trolley ahead of it using a light rigid horizontal rod. The track is level. The driving force is 34 N. The resistances on the powered and unpowered trolleys are 4 N and 6 N respectively.',
    [part('Find their common forward acceleration.', 'm s⁻²', 3), part('Find the magnitude of the thrust in the rod.', 'N', 15)],
    'For the pair, the net forward force is 34 − 4 − 6 = 24 N, so a = 24 ÷ 8 = 3 m s⁻². The force on the unpowered trolley obeys thrust − 6 = 3 × 3, giving a thrust of 15 N.'),
  challenge(4, 'braking-transmitted-by-rod',
    'Two carts move to the right on a smooth horizontal track, joined by a light rigid rod. The front cart has mass 4 kg and the rear cart has mass 2 kg. A constant 18 N braking force acts to the left on the front cart only.',
    [part('Find the magnitude of the deceleration while the carts are moving right.', 'm s⁻²', 3),
     part('Find the magnitude of the force that the rod exerts on the rear cart.', 'N', 6)],
    'For the pair the only horizontal external force is 18 N leftwards, so the acceleration is 18 ÷ 6 = 3 m s⁻² leftwards. The rod pushes the rear cart to the left with force 2 × 3 = 6 N and is in compression.'),
  challenge(4, 'string-slack-after-load-lands',
    'A 3 kg particle A on a rough horizontal table is joined by a taut light inextensible string over a smooth pulley to a hanging 2 kg particle B. They start from rest. B is initially 1.25 m above the floor and stops without bouncing when it reaches it. The string then goes slack. The coefficient of friction for A is 0.25 and the table is long enough for A to stop on it. Take g = 10 m s⁻².',
    [part('Find the speed of A immediately before B reaches the floor.', 'm s⁻¹', 2.5),
     part('Find the total distance that A travels before stopping.', 'm', 2.5)],
    'While the string is taut, the driving weight is 20 N and friction is 7.5 N. The common acceleration is (20 − 7.5) ÷ 5 = 2.5 m s⁻². After 1.25 m the common speed satisfies v² = 2 × 2.5 × 1.25, so v = 2.5 m s⁻¹. Once the string is slack, A decelerates at 7.5 ÷ 3 = 2.5 m s⁻². Its stopping distance is another 1.25 m, making 2.5 m in total.'),
  challenge(4, 'two-tensions-in-service-lift',
    'A cable raises a 120 kg service lift from rest with constant acceleration. In the first 2 s the lift rises 3 m. The tension then changes to a new constant value, and the lift rises a further 3 m before coming to rest. Take g = 10 m s⁻².',
    [part('Find the cable tension during the first stage.', 'N', 1380), part('Find the cable tension during the second stage.', 'N', 1020)],
    'In the first stage, 3 = ½a × 2² gives a = 1.5 m s⁻² upwards and a final speed of 3 m s⁻¹. In the second, 0 = 3² + 2a × 3 gives a = −1.5 m s⁻² when upwards is positive. With T − 1200 = 120a, the tensions are 1380 N and 1020 N respectively.'),
  challenge(4, 'angled-pull-with-friction-up-slope',
    'A 5 kg box on a rough slope starts moving up the slope under a 50 N pull. The slope angle θ has sin θ = 0.6 and cos θ = 0.8. The pull makes angle α above the upslope direction, where sin α = 0.6 and cos α = 0.8. The coefficient of friction is 0.25 and g = 10 m s⁻².',
    [part('Find the normal reaction while the box is moving.', 'N', 10),
     part('Find its speed after moving 6 m from rest to 3 significant figures.', 'm s⁻¹', 4.24, 0.005)],
    'The normal reaction is 50 × 0.8 − 50 × 0.6 = 10 N. The upslope force is 50 × 0.8 = 40 N, opposed by 30 N from weight and 2.5 N friction. The acceleration is (40 − 30 − 2.5) ÷ 5 = 1.5 m s⁻². After 6 m, v = √(2 × 1.5 × 6) = 4.24 m s⁻¹.'),
];

